-- Development seed: Anvaya sample catalogue (original placeholder saris and blouses).
-- Generated by scripts/generate-seed.ts. Safe to re-run: skips products that already exist.
select set_config('app.inventory_write', 'on', true);


-- Meenakshi Temple-Border Kanjivaram
do $$
declare p_meenakshi_temple_border_kanjivaram uuid; v_color uuid; v_variant uuid; v_asset uuid;
begin
  if exists (select 1 from public.products where slug = 'meenakshi-temple-border-kanjivaram') then return; end if;
  values ('Meenakshi Temple-Border Kanjivaram', 'meenakshi-temple-border-kanjivaram', 'ANV-MTK', (select id from public.categories where slug = 'kanjivaram'), 'women', 'A heavy mulberry silk with a contrast temple border, coin buttas across the body and a banded zari pallu.', 'The temple border is the signature of Kanchipuram: rows of gopuram teeth rising from the selvedge into the body. Here it is woven in a contrasting colour and joined to the body by korvai, the interlocking technique that keeps the two colours separate thread by thread.

Small kasu (coin) buttas are scattered across the body, and the pallu repeats the border colour in broad zari bands.

- Pure mulberry silk with zari
- Contrast border joined by korvai
- 5.5 m sari with an unstitched 0.8 m blouse piece', 3850000, null, 'draft', now() - interval '19 days', true, false, true, false, array['kanjivaram', 'silk', 'temple border', 'bridal', 'zari']::text[], 'Option', null, null, 'Meenakshi Temple-Border Kanjivaram — Kumkum and Mango', 'A heavy mulberry silk with a contrast temple border, coin buttas across the body and a banded zari pallu.')
  returning id into p_meenakshi_temple_border_kanjivaram;
  update public.products set status = 'published' where id = p_meenakshi_temple_border_kanjivaram;
end $$;

